sed -i 's/GAP = 10600.0/GAP = 11000.0/' auto_plan.py && python auto_plan.py 2>&1|tail -3 && python - <<'EOF'
import json
plan=json.load(open('_plan_times.json'))
out=[]
for i,w in enumerate(plan):
    d={"file":'avatar/A%d.mp4'%i,"frame":"refs/avatar.png","startMs":w['t'],"endMs":w['t']+w['dur']}
    if i%3==1:
        d['foto']='pX%02d'%i
        d['lado']='der' if (i//3)%2 else 'izq'
    out.app

